<?php $e = static fn (mixed $value): string => App\Core\View::e($value); ?>
<section class="public-news"><header><p class="eyebrow"><?= $e($championship['name']) ?></p><h1>Notícias</h1><p>Informações recentes do campeonato.</p></header><form class="filter-bar" method="get" action="<?= $e(App\Core\Config::url('/campeonatos/' . $championship['slug'] . '/noticias')) ?>"><label>Buscar <input name="q" value="<?= $e($search) ?>"></label><button type="submit">Buscar</button></form>
    <div class="news-grid"><?php foreach ($items as $item): ?><article class="news-card"><?php if (!empty($item['cover_image_path'])): ?><img src="<?= $e(App\Core\Config::url('/campeonatos/' . $championship['slug'] . '/noticias/' . $item['slug'] . '/capa')) ?>" alt="Capa: <?= $e($item['title']) ?>"><?php endif; ?><p class="eyebrow"><?= !empty($item['featured']) ? 'Destaque' : 'Noticia' ?></p><h2><a href="<?= $e(App\Core\Config::url('/campeonatos/' . $championship['slug'] . '/noticias/' . $item['slug'])) ?>"><?= $e($item['title']) ?></a></h2><p><?= $e($item['summary']) ?></p><small><?= $e($item['published_at']) ?> | <?= $e($item['author_name']) ?></small></article><?php endforeach; ?><?php if (!$items): ?><p>Nenhuma noticia publicada.</p><?php endif; ?></div>
    <?php if ($pages > 1): ?><nav class="pagination" aria-label="Paginação"><?php for ($index = 1; $index <= $pages; $index++): ?><a class="<?= $index === $page ? 'active' : '' ?>" href="<?= $e(App\Core\Config::url('/campeonatos/' . $championship['slug'] . '/noticias?page=' . $index . '&q=' . urlencode($search))) ?>"><?= $index ?></a><?php endfor; ?></nav><?php endif; ?>
</section>
